// Charge in empty space, then lure an opponent into the prepared altar.
const VACANT_ALTAR_SIGNATURE=['空席の祭壇',24,8,'照準地点に6秒の祭壇。半径140に敵がいない間だけ力をため、最大3秒。設置0.5秒後から、射線の通る敵が入ると円内へ100%＋蓄積1秒につき100%（最大400%）の爆発。最初から敵がいる場合は100%。範囲補正は半径だけに作用。自分が500を超えて離れる・壁に隠れる・死亡・地域移動で解除。再発動で置き換える。','M8 43H44M13 37H39L35 29H17ZM26 24V7M18 15L26 7L34 15M7 21L12 26M45 21L40 26'];
SIGNATURE_SKILLS.push(VACANT_ALTAR_SIGNATURE);Object.assign(GEM.crafted_5_5,{name:VACANT_ALTAR_SIGNATURE[0],cost:24,cool:8,desc:VACANT_ALTAR_SIGNATURE[3],ability:null,signature:101,tags:['spell','area']});
SIGNATURE_AUDIO.push(['vacantaltar',360,.4]);SKILL_AUDIO_FAMILIES.heavy.add('vacantaltar');
function vacantAltarValid(s){return s.owner===p&&s.world===dungeon&&!s.finished&&!dead&&p?.hp>0&&dist(p,s)<=500&&lineClear(p,s);}
function vacantAltarTargets(s){return enemies.filter(e=>e.hp>0&&dist(e,s)<=140*s.build.radius&&lineClear(s,e));}
const vacantAltarCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{const result=vacantAltarCastBase(build,...args);if(GEM[build.type]?.signature!==101)return result;const s=signatureSpells.at(-1);if(s?.mode!==101)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==101||v===s);Object.assign(s,{owner:p,world:dungeon,finished:false,charge:0,target:null});return result;};
const vacantAltarStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==101)return vacantAltarStepBase(s,dt);if(!vacantAltarValid(s))return false;if(paused||!Number.isFinite(dt)||dt<=0)return true;const targets=vacantAltarTargets(s);s.time+=dt;if(s.time>=6){s.finished=true;return false;}if(!targets.length){s.charge=Math.min(3,s.charge+dt);return true;}if(s.time+1e-8<.5)return true;s.finished=true;for(const e of targets)if(e.hp>0&&enemies.includes(e))spellHit(e,s.damage*(1+s.charge),s.build);burst(s.x,s.y,140*s.build.radius,ELEMENTS[s.build.elements[0]].color);playSignatureAudio(101,true,s.x,s.y);return false;};
const vacantAltarPaintBase=paintSignatureSpells;paintSignatureSpells=()=>{vacantAltarPaintBase();for(const s of signatureSpells){if(s.mode!==101||!vacantAltarValid(s)||!visibleAt(s.x,s.y))continue;const col=s.charge>=3?'#ffe49a':ELEMENTS[s.build.elements[0]].color;groundRing(s.x,s.y,140*s.build.radius,col,2);groundRing(s.x,s.y,(20+30*s.charge)*s.build.radius,col,3);for(let i=0;i<3;i++){const a=i*Math.PI*2/3-Math.PI/2;const q=project(s.x+Math.cos(a)*45,s.y+Math.sin(a)*45);glowAt(q,5,s.charge>=i+1?'#fff1ba':col,s.charge>=i+1?.9:.25);}}};
const vacantAltarStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===101?{label:'祭壇 '+Math.round((1+s.charge)*100)+'% · 敵を誘導',value:s.charge/3,waiting:true}:vacantAltarStatusBase(s);
